namespace FCG.Games.Domain.Entities;
public enum PurchaseStatus{Pending,Approved,Failed}
public sealed class Purchase{private Purchase(){}public Guid Id{get;private set;}public int UserId{get;private set;}public int GameId{get;private set;}public decimal OriginalAmount{get;private set;}public decimal DiscountPercentage{get;private set;}public decimal FinalAmount{get;private set;}public PurchaseStatus Status{get;private set;}public Guid? PaymentId{get;private set;}public DateTime CreatedAtUtc{get;private set;}
public static Purchase Create(int userId,int gameId,decimal amount,int libraryCount){var discount=libraryCount>5?15m:0m;return new(){Id=Guid.NewGuid(),UserId=userId,GameId=gameId,OriginalAmount=amount,DiscountPercentage=discount,FinalAmount=decimal.Round(amount*(1-discount/100m),2),Status=PurchaseStatus.Pending,CreatedAtUtc=DateTime.UtcNow};}public void Approve(Guid paymentId){Status=PurchaseStatus.Approved;PaymentId=paymentId;}public void Fail(Guid paymentId){Status=PurchaseStatus.Failed;PaymentId=paymentId;}}
public sealed class LibraryItem{private LibraryItem(){}public int Id{get;private set;}public int UserId{get;private set;}public int GameId{get;private set;}public DateTime AcquiredAtUtc{get;private set;}public static LibraryItem Create(int u,int g)=>new(){UserId=u,GameId=g,AcquiredAtUtc=DateTime.UtcNow};}
